CREATE TABLE communities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, slug text NOT NULL UNIQUE, description text, visibility text NOT NULL DEFAULT 'PUBLIC', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE community_members (community_id uuid NOT NULL REFERENCES communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'MEMBER', joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(community_id,user_id));
CREATE INDEX idx_community_members_user ON community_members(user_id);
CREATE TABLE media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), storage_key text NOT NULL UNIQUE, mime_type text NOT NULL, size_bytes bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), media_asset_id uuid REFERENCES media_assets(id), caption text, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_stories_active ON stories(expires_at DESC);
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_notifications_user_created ON notifications(user_id,created_at DESC);
CREATE TABLE call_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid REFERENCES chat_rooms(id), initiated_by uuid NOT NULL REFERENCES users(id), call_type text NOT NULL, status text NOT NULL DEFAULT 'RINGING', started_at timestamptz, ended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, currency text NOT NULL DEFAULT 'NGN', balance_minor bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id uuid NOT NULL REFERENCES wallet_accounts(id) ON DELETE CASCADE, direction text NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>0), currency text NOT NULL, kind text NOT NULL, idempotency_key text NOT NULL UNIQUE, provider_reference text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_wallet_ledger_wallet_created ON wallet_ledger_entries(wallet_id,created_at DESC);
CREATE TABLE creator_accounts (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, display_name text, payout_status text NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE business_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), business_name text NOT NULL, status text NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now());
